<?php
declare(strict_types=1);
session_start();
require dirname(__DIR__,2).'/config/config.php';
function stores_dashboard_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())stores_dashboard_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))stores_dashboard_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);if(($_SESSION['role']??'')!=='storekeeper')stores_dashboard_json(403,['ok'=>false,'message'=>'This dashboard is for Stores accounts.']);$uid=(int)$_SESSION['user_id'];$school=filter_var($_GET['school_id']??null,FILTER_VALIDATE_INT);if(!$school)stores_dashboard_json(422,['ok'=>false,'message'=>'Choose a school.']);
try{$db=db();$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())stores_dashboard_json(403,['ok'=>false,'message'=>'That school is outside your access.']);$q=$db->prepare('SELECT COUNT(*) item_count,COUNT(reorder_threshold) tracked_items FROM inventory_items WHERE school_id=?');$q->execute([$school]);$stock=$q->fetch()?:['item_count'=>0,'tracked_items'=>0];$q=$db->prepare('SELECT COUNT(*) FROM inventory_items WHERE school_id=? AND reorder_threshold IS NOT NULL AND quantity<=reorder_threshold');$q->execute([$school]);$low=(int)$q->fetchColumn();$q=$db->prepare('SELECT COALESCE(SUM(quantity*last_unit_cost),0) value,COUNT(CASE WHEN quantity>0 AND last_unit_cost IS NULL THEN 1 END) unvalued_items FROM inventory_items WHERE school_id=?');$q->execute([$school]);$valuation=$q->fetch()?:['value'=>0,'unvalued_items'=>0];$q=$db->prepare("SELECT COUNT(*) FROM inventory_requests WHERE school_id=? AND status='pending'");$q->execute([$school]);$pending=(int)$q->fetchColumn();$q=$db->prepare("SELECT COUNT(*) FROM inventory_requests WHERE school_id=? AND status='approved'");$q->execute([$school]);$approved=(int)$q->fetchColumn();$q=$db->prepare('SELECT m.id,m.movement_type,m.quantity,m.note,m.created_at,i.item_name,i.unit,u.name recorded_by FROM inventory_movements m JOIN inventory_items i ON i.id=m.item_id AND i.school_id=m.school_id JOIN users u ON u.id=m.recorded_by WHERE m.school_id=? ORDER BY m.created_at DESC,m.id DESC LIMIT 10');$q->execute([$school]);stores_dashboard_json(200,['ok'=>true,'data'=>['item_count'=>(int)$stock['item_count'],'tracked_items'=>(int)$stock['tracked_items'],'low_stock'=>$low,'pending_requests'=>$pending,'approved_requests'=>$approved,'estimated_value'=>(float)$valuation['value'],'unvalued_items'=>(int)$valuation['unvalued_items'],'recent_movements'=>$q->fetchAll()]]);}catch(Throwable $e){error_log('Stores dashboard request failed: '.$e->getMessage());stores_dashboard_json(500,['ok'=>false,'message'=>'Stores dashboard data could not be loaded.']);}
